$idm_2023$::jsonb) AS data(
    kode_desa TEXT,
    desa TEXT,
    distrik TEXT,
    kabupaten TEXT,
    iks NUMERIC,
    ike NUMERIC,
    ikl NUMERIC,
    nilai_idm NUMERIC,
    status_idm TEXT
  )
)
INSERT INTO sikampung_data (
  tahun_anggaran,
  kode_desa,
  desa,
  distrik,
  kabupaten,
  iks,
  ike,
  ikl,
  nilai_idm,
  status_idm
)
SELECT
  target.tahun_anggaran,
  kode_desa,
  desa,
  distrik,
  kabupaten,
  iks,
  ike,
  ikl,
  nilai_idm,
  status_idm
FROM source
CROSS JOIN (VALUES ('2025'), ('2026')) AS target(tahun_anggaran)
ON CONFLICT (tahun_anggaran, (LOWER(kode_desa)))
DO UPDATE SET
  desa = EXCLUDED.desa,
  distrik = EXCLUDED.distrik,
  kabupaten = EXCLUDED.kabupaten,
  iks = EXCLUDED.iks,
  ike = EXCLUDED.ike,
  ikl = EXCLUDED.ikl,
  nilai_idm = EXCLUDED.nilai_idm,
  status_idm = EXCLUDED.status_idm,
  updated_at = NOW();
